<?php
declare(strict_types=1);
require_once __DIR__.'/toolbar.php';
const ACCOUNTING_TABS=['overview'=>'Today','review'=>'Review & post','studentledger'=>'Student ledger','transactions'=>'Expenses & refunds','ledger'=>'General Ledger','accounts'=>'Accounts','mappings'=>'Mappings','reconcile'=>'Reconcile','budgets'=>'Budgets','assets'=>'Assets','financial'=>'Financial reports','periods'=>'Close period'];
function accounting_nav(string $tab): void {
    $groups=['Daily work'=>['overview','review','studentledger','transactions'],'Books & setup'=>['ledger','accounts','mappings','reconcile'],'Planning & reporting'=>['budgets','assets','financial'],'Period control'=>['periods']];
    $descriptions=[
        'overview'=>'Start with the tasks that need your attention today.',
        'review'=>'Review transactions before they reach the General Ledger.',
        'studentledger'=>'Find a student and review their assessments, payments and balance.',
        'transactions'=>'Prepare expenses, refunds and other transactions for review.',
        'ledger'=>'View posted entries and their debit and credit details.',
        'accounts'=>'Manage the chart of accounts and review account balances.',
        'mappings'=>'Connect school transactions to the correct accounting accounts.',
        'reconcile'=>'Match posted cash and bank transactions to your statement.',
        'budgets'=>'Compare approved budgets with posted actuals.',
        'assets'=>'Manage school assets and prepare depreciation entries.',
        'financial'=>'Review financial statements and student receivables.',
        'periods'=>'Close a finished accounting period or reopen it with a reason.'
    ];
    echo '<nav class="accounting-navigation d-print-none" aria-label="Accounting tasks">';
    foreach($groups as $label=>$tabs) {
        echo '<div class="accounting-nav-group"><span class="accounting-nav-label">'.h($label).'</span><div class="accounting-nav-links">';
        foreach($tabs as $key) echo '<a class="accounting-nav-link'.($tab===$key?' is-active':'').'" href="'.h(url('accounting',['tab'=>$key])).'"'.($tab===$key?' aria-current="page"':'').'>'.h(ACCOUNTING_TABS[$key]).'</a>';
        echo '</div></div>';
    }
    echo '</nav><div class="accounting-context"><div><h2>'.h(ACCOUNTING_TABS[$tab]).'</h2><p>'.h($descriptions[$tab]).'</p></div><span class="accounting-flow d-print-none">Review <span aria-hidden="true">→</span> Post <span aria-hidden="true">→</span> Reconcile <span aria-hidden="true">→</span> Reports</span></div>';
}
function accounting_new_action(string $action): bool {
    $id=(int)($_POST['entry_id']??0);$reason=(string)($_POST['reason']??'');
    switch($action){
        case 'classify':AccountingWorkflow::classify($id,$_POST);break;
        case 'submit':AccountingWorkflow::submit($id);break;
        case 'approve':AccountingWorkflow::review($id,$reason,true);break;
        case 'return':AccountingWorkflow::review($id,$reason,false);break;
        case 'post':AccountingWorkflow::post($id);break;
        case 'reverse_posted':AccountingWorkflow::reverse($id,$reason,(string)($_POST['reversal_date']??''));break;
        case 'discard':AccountingWorkflow::cancelDraft($id,$reason);break;
        case 'document':$id=AccountingWorkflow::document($_POST);flash('success','Draft saved. Send it for review when ready.');redirect('accounting',['tab'=>'review','entry'=>$id,'status'=>'DRAFT']);
        case 'supplier':AccountingWorkflow::supplier($_POST);break;
        case 'budget':AccountingWorkflow::budget($_POST);break;
        case 'asset':AccountingWorkflow::asset($_POST);break;
        case 'depreciate':$id=AccountingWorkflow::depreciate((int)($_POST['asset_id']??0),(string)($_POST['month']??''));redirect('accounting',['tab'=>'review','entry'=>$id,'status'=>'DRAFT']);
        case 'close_period':case 'reopen_period':AccountingWorkflow::period((string)($_POST['start_date']??''),(string)($_POST['end_date']??''),$reason,$action==='close_period');break;
        default:return false;
    }
    flash('success',match($action){'post'=>'Posted successfully. Related receipts are now locked.','reverse_posted'=>'Posting reversed. The original record remains. For receipts, Cashier must still void the receipt.','approve'=>'Approved. The entry is ready to post.','submit'=>'Sent to Accounting for review.','return'=>'Returned to draft. Review the correction note.','discard'=>'Draft discarded. Its audit history remains.',default=>'Saved successfully.'});
    header('Location: '.$_SERVER['REQUEST_URI']);exit;
}
function accounting_workspace(string $tab): void {
    $edit=Auth::can('accounting.edit');$review=Auth::can('accounting.review');$post=Auth::can('accounting.post');$close=Auth::can('accounting.close');
    $accounts=Accounting::accounts(true);
