    $field=function(string $name,string $label,string $type='text',string $value='',bool $required=true) {static $counter=0;$control='accountingField'.++$counter;echo '<label class="form-label" for="'.$control.'">'.h($label).'</label><input id="'.$control.'" class="form-control mb-2" name="'.h($name).'" type="'.h($type).'" value="'.h($value).'"'.($required?' required':'').'>';};
