        echo '<form id="accountingReviewFilters" data-record-filters method="get" class="form-section row g-2"><input type="hidden" name="r" value="accounting"><input type="hidden" name="tab" value="review"><input type="hidden" name="apply" value="1"><div class="col-sm-3"><label class="form-label">Status</label><select name="status" class="form-select">';foreach(['DRAFT'=>'Draft','REVIEW'=>'Needs review / ready to post','POSTED'=>'Posted / reversed','CANCELLED'=>'Cancelled'] as $k=>$v)echo '<option value="'.$k.'"'.($status===$k?' selected':'').'>'.$v.'</option>';echo '</select></div><div class="col-sm-2">';$field('from','From','date',$from??'',false);echo '</div><div class="col-sm-2">';$field('to','To','date',$to??'',false);echo '</div><div class="col-sm-2"><label class="form-label">School year</label><select class="form-select" name="sy">'.sy_options($sy,true).'</select></div><div class="col-sm-3">';$field('q','Student, receipt, reference','text',$q,false);echo '</div><div><button class="btn btn-primary">Show entries</button></div></form>';
        $w=['j.status=?'];$params=[$status];if($from){$w[]='j.entry_date>=?';$params[]=$from;}if($to){$w[]='j.entry_date<=?';$params[]=$to;}if($sy){$w[]='r.school_year=?';$params[]=$sy;}if($q!==''){$w[]='(j.memo LIKE ? OR j.entry_no LIKE ? OR r.student_number LIKE ?)';array_push($params,'%'.$q.'%','%'.$q.'%','%'.$q.'%');}
        $entries=RecordList::query('SELECT j.*,r.student_number,r.student_name,r.school_year,r.term,(SELECT SUM(debit) FROM sis_journal_lines WHERE journal_id=j.id) AS amount FROM sis_journal j LEFT JOIN sis_registrations r ON r.id=j.registration_id WHERE '.implode(' AND ',$w).' ORDER BY j.id DESC LIMIT 300',$params);
