            echo '<div class="table-responsive"><table class="table"><thead><tr><th>Account</th><th>Debit</th><th>Credit</th><th>Note</th></tr></thead><tbody>';foreach(Db::all('SELECT l.*,a.code,a.name FROM sis_journal_lines l JOIN sis_accounts a ON a.id=l.account_id WHERE journal_id=?',[$entry]) as $l)echo '<tr><td>'.h($l['code'].' · '.$l['name']).'</td><td>'.Money::fmt(Money::cents($l['debit'])).'</td><td>'.Money::fmt(Money::cents($l['credit'])).'</td><td>'.h($l['memo']).'</td></tr>';echo '</tbody></table></div>';
