></div><button class="btn btn-primary mt-3">Save draft</button></form></section><details class="form-section"><summary>Add a supplier / payee</summary><form method="post">'.csrf_field().'<input name="action" type="hidden" value="supplier">';$field('name','Supplier name');$field('reference_no','Supplier reference');echo '<button class="btn btn-primary">Save supplier</button></form></details>';}
    }
    elseif($tab==='budgets'){
        echo '<section class="form-section"><h2 class="h5">Budget versus actual</h2><p>Actuals use posted entries in each budget’s date range, fund and department. Positive variance = budget minus actual.</p><div class="table-responsive"><table class="table"><thead><tr><th>School year / dates</th><th>Department / fund</th><th>Account</th><th>Budget</th><th>Actual</th><th>Variance</th></tr></thead><tbody>';foreach(RecordList::query('SELECT b.*,a.code,a.name,a.type FROM sis_accounting_budgets b JOIN sis_accounts a ON a.id=b.account_id ORDER BY b.start_date DESC,b.department,a.code') as $r){$net=Money::cents(Db::val("SELECT COALESCE(SUM(l.debit-l.credit),0) FROM sis_journal_lines l JOIN sis_journal j ON j.id=l.journal_id WHERE j.status='POSTED' AND j.entry_date BETWEEN ? AND ? AND j.fund=? AND j.department=? AND l.account_id=?",[$r['start_date'],$r['end_date'],$r['fund'],$r['department'],$r['account_id']]));$actual=$r['type']==='REVENUE'?-$net:$net;echo '<tr><td>'.h($r['school_year'].' · '.$r['start_date'].' to '.$r['end_date']).'</td><td>'.h($r['department'].' · '.$r['fund']).'</td><td>'.h($r['code'].' · '.$r['name']).'</td><td>'.Money::fmt(Money::cents($r['amount'])).'</td><td>'.Money::fmt($actual).'</td><td>'.Money::fmt(Money::cents($r['amount'])-$actual).'</td></tr>';}echo '</tbody></table></div><button class="btn btn-outline-secondary" data-print>Print report</button></section>';
        if($edit){echo '<section class="form-section"><h2 class="h5">Set a budget</h2><form method="post">'.csrf_field().'<input type="hidden" name="action" value="budget">';$field('start_date','From','date',date('Y-01-01'));$field('end_date','To','date',date('Y-12-31'));echo '<label class="form-label">School year</label><select class="form-select mb-2" name="school_year" required>'.sy_options('',false).'</select>';$dimensions();$select('account_id','Budget account',array_values(array_filter($accounts,fn($a)=>in_array($a['type'],['EXPENSE','REVENUE','CONTRA_REVENUE'],true))));$field('amount','Budget amount ₱');echo '<p class="small">Saving the same dates, school year, department, fund and account updates that budget.</p><button class="btn btn-primary">Save budget</button></form></section>';}
    }
    elseif($tab==='assets'){
        echo '<section class="form-section"><h2 class="h5">School assets</h2><p>Register equipment after recording its purchase through an expense / asset transaction. Straight-line depreciation begins in the acquisition month. Each month is drafted once for review.</p><div class="table-responsive"><table class="table"><thead><tr><th>Asset</th><th>Cost / residual</th><th>Life</th><th>Posted depreciation</th><th>Net book value</th><th></th></tr></thead><tbody>';foreach(RecordList::query('SELECT * FROM sis_accounting_assets ORDER BY id DESC') as $a){$dep=Money::cents(Db::val("SELECT COALESCE(SUM(d.amount),0) FROM sis_accounting_documents d JOIN sis_journal j ON j.id=d.journal_id WHERE d.kind='DEPRECIATION' AND d.reference_no LIKE ? AND j.status='POSTED' AND j.reversed_by_id IS NULL",['ASSET-'.$a['id'].'-%']));echo '<tr><td>'.h($a['asset_code'].' · '.$a['name']).'</td><td>'.Money::fmt(Money::cents($a['cost'])).' / '.Money::fmt(Money::cents($a['residual'])).'</td><td>'.(int)$a['useful_months'].' months</td><td>'.Money::fmt($dep).'</td><td>'.Money::fmt(Money::cents($a['cost'])-$dep).'</td><td>';if($edit)echo '<form method="post" class="d-flex gap-2">'.csrf_field().'<input type="hidden" name="action" value="depreciate"><input type="hidden" name="asset_id" value="'.(int)$a['id'].'"><input type="month" name="month" class="form-control" required value="'.date('Y-m').'"><button class="btn btn-outline-primary">Draft depreciation</button></form>';echo '</td></tr>';}echo '</tbody></table></div></section>';
        if($edit){echo '<details class="form-section"><summary>Register an asset</summary><form method="post">'.csrf_field().'<input type="hidden" name="action" value="asset">';$field('asset_code','Asset code');$field('name','Asset name');$field('acquired_date','Acquired','date',date('Y-m-d'));$field('cost','Cost ₱');$field('residual','Residual value ₱','text','0');$field('useful_months','Useful life in months','number','60');$select('asset_account_id','Equipment account',array_values(array_filter($accounts,fn($a)=>$a['type']==='ASSET')));$select('expense_account_id','Depreciation expense account',array_values(array_filter($accounts,fn($a)=>$a['type']==='EXPENSE')));$select('accumulated_account_id','Accumulated depreciation account',array_values(array_filter($accounts,fn($a)=>$a['type']==='ASSET')));$dimensions();echo '<button class="btn btn-primary">Register asset</button></form></details>';}
    }
    elseif($tab==='financial'){
        echo '<section class="form-section"><h2 class="h5">Financial statements</h2><div class="d-flex flex-wrap gap-2">';foreach(['trial_balance'=>'Trial Balance','general_ledger'=>'General Ledger','income_statement'=>'Income Statement','balance_sheet'=>'Balance Sheet','ar_ledger'=>'Student Receivables','collections_by_account'=>'Collections by Account'] as $k=>$v)echo '<a class="btn btn-outline-primary" href="'.h(url('reports',['rep'=>$k,'run'=>1])).'">'.h($v).'</a>';echo '</div></section>';
        $asof=In::date($_GET,'asof')??date('Y-m-d');$fund=isset(AccountingWorkflow::FUNDS[$_GET['fund']??''])?$_GET['fund']:'';$dept=trim((string)($_GET['department']??''));echo '<section class="form-section"><h2 class="h5">Balances by fund and department</h2><form id="accountingFinancialFilters" data-record-filters method="get"><input type="hidden" name="r" value="accounting"><input type="hidden" name="tab" value="financial"><input type="hidden" name="apply" value="1">';$field('asof','As of','date',$asof);echo '<label class="form-label">Fund</label><select class="form-select mb-2" name="fund"><option value="">All funds</option>';foreach(AccountingWorkflow::FUNDS as $k=>$v)echo '<option value="'.$k.'"'.($fund===$k?' selected':'').'>'.h($v).'</option>';echo '</select><label class="form-label">Department</label><select class="form-select mb-3" name="department"><option value="">All departments</option>';foreach(Db::col("SELECT DISTINCT department FROM sis_journal WHERE status='POSTED' ORDER BY department") as $v)echo '<option'.($dept===$v?' selected':'').'>'.h($v).'</option>';echo '</select><button class="btn btn-primary">Show balances</button></form>';
        $balances=RecordList::applied()?Accounting::balances($asof,null,$fund?:null,$dept?:null):[];$dr=0;$cr=0;echo '<div class="table-responsive mt-3"><table class="table"><thead><tr><th>Account</th><th>Type</th><th>Debit balance</th><th>Credit balance</th></tr></thead><tbody>';foreach(Accounting::accounts() as $a){$b=$balances[(int)$a['id']]??0;if(!$b)continue;$dr+=max(0,$b);$cr+=max(0,-$b);echo '<tr><td>'.h($a['code'].' · '.$a['name']).'</td><td>'.h($a['type']).'</td><td>'.Money::fmt(max(0,$b)).'</td><td>'.Money::fmt(max(0,-$b)).'</td></tr>';}echo '</tbody><tfoot><tr><th colspan="2">Total</th><th>'.Money::fmt($dr).'</th><th>'.Money::fmt($cr).'</th></tr></tfoot></table></div><button class="btn btn-outline-secondary" data-print>Print report</button></section>';
        echo '<section class="form-section"><h2 class="h5">Receivables aging</h2><p>Age is counted from the confirmed assessment date, not a contractual due date. This shows operational student balances, including payments not yet posted to the General Ledger.</p><div class="table-responsive"><table class="table"><thead><tr><th>Student / period</th><th>0–30 days</th><th>31–60</th><th>61–90</th><th>Over 90</th></tr></thead><tbody>';foreach(RecordList::query("SELECT * FROM sis_registrations WHERE status<>'CANCELLED' AND locked_at IS NOT NULL AND total_amount>amount_paid ORDER BY student_name,school_year") as $r){$age=(int)(new DateTimeImmutable(substr($r['locked_at'],0,10)))->diff(new DateTimeImmutable('today'))->format('%r%a');$bucket=$age<=30?0:($age<=60?1:($age<=90?2:3));echo '<tr><td>'.h($r['student_name'].' · '.$r['school_year'].' '.$r['term']).'</td>';for($i=0;$i<4;$i++)echo '<td>'.($i===$bucket?Money::fmt(Registration::balance($r)):'—').'</td>';echo '</tr>';}echo '</tbody></table></div></section>';
    }
    elseif($tab==='periods'){
        echo '<section class="form-section"><h2 class="h5">Accounting periods</h2><p>Closing blocks new entries and posting in that date range. Finish pending entries, void reversed receipts, and reconcile cash / bank lines first. Reopen the exact period with a reason when an authorized correction is needed.</p><div class="table-responsive"><table class="table"><thead><tr><th>From</th><th>To</th><th>Status</th><th>Last reason</th><th>Changed</th></tr></thead><tbody>';foreach(RecordList::query('SELECT * FROM sis_accounting_periods ORDER BY start_date DESC') as $r)echo '<tr><td>'.h($r['start_date']).'</td><td>'.h($r['end_date']).'</td><td>'.h($r['status']).'</td><td>'.h($r['reason']).'</td><td>'.h($r['changed_at']).'</td></tr>';echo '</tbody></table></div></section>';
        if($close){echo '<section class="form-section"><h2 class="h5">Close or reopen</h2><form method="post" data-confirm="Apply this accounting period change?" data-loading-label="Checking accounting period…">'.csrf_field();$field('start_date','Period starts','date',date('Y-m-01'));$field('end_date','Period ends','date',date('Y-m-t'));$field('reason','Reason (at least 8 characters)');echo '<button class="btn btn-primary" name="action" value="close_period">Close period</button> <button class="btn btn-outline-secondary" name="action" value="reopen_period">Reopen period</button></form></section>';}
    }
    echo '<script src="assets/accounting-workflow.js?v=20261021toolbar" defer></script>';layout_end();
}
